package org.islamicmute.app.adb

import java.math.BigInteger
import java.security.MessageDigest
import java.security.SecureRandom

/**
 * SPAKE2 over edwards25519, byte-compatible with BoringSSL's `SPAKE2_*` functions (crypto/curve25519/spake25519.cc,
 * Apache-2.0), which Android's adbd uses for "Pair device with pairing code". Ported from that file:
 *  - the M and N points (from its comment; generated by hashing a seed string until it decodes as a point),
 *  - the private scalar: 64 random bytes reduced mod l, then multiplied by the cofactor 8 (not reduced again),
 *  - the password scalar: SHA-512(password) reduced mod l, then l, 2l and 4l added as needed to make it a multiple
 *    of 8 (BoringSSL's fix for a missing cofactor clear, which changes the bytes on the wire),
 *  - the transcript: SHA-512 over 8-byte little-endian length-prefixed fields, Alice's name and message first, ending
 *    with the shared point and the full 64-byte password hash.
 * adb's client is Alice ("adb pair client\0"), the phone's adbd is Bob ("adb pair server\0").
 */
class Spake2 internal constructor(
    private val alice: Boolean,
    private val myName: ByteArray,
    private val theirName: ByteArray,
    password: ByteArray,
    privateScalar: BigInteger,
) {
    private val privateKey = privateScalar
    private val passwordHash: ByteArray = sha512(password)
    private val passwordScalar: BigInteger = passwordScalar(passwordHash)

    /** Our 32-byte message: privateKey*B + w*(M for Alice, N for Bob). */
    val message: ByteArray = (Ed25519.BASE.times(privateKey) + (if (alice) M else N).times(passwordScalar)).encode()

    /**
     * The 64-byte shared key from the peer's message. Both sides get the same key only with the same password;
     * a wrong one shows up later, when the peer cannot decrypt what this key encrypts.
     * Throws [IllegalArgumentException] when [theirMessage] is not a point.
     */
    fun processMessage(theirMessage: ByteArray): ByteArray {
        require(theirMessage.size == 32) { "SPAKE2 message must be 32 bytes" }
        val qStar = Ed25519.decode(theirMessage)
        val q = qStar - (if (alice) N else M).times(passwordScalar)
        val shared = q.times(privateKey).encode()
        val sha = MessageDigest.getInstance("SHA-512")
        fun put(b: ByteArray) {
            val len = ByteArray(8); var n = b.size.toLong()
            for (i in 0 until 8) { len[i] = (n and 0xff).toByte(); n = n ushr 8 }
            sha.update(len); sha.update(b)
        }
        if (alice) { put(myName); put(theirName); put(message); put(theirMessage) }
        else { put(theirName); put(myName); put(theirMessage); put(message) }
        put(shared)
        put(passwordHash)
        return sha.digest()
    }

    companion object {
        /** BoringSSL's points, as encoded in spake25519.cc (decimal x/y in its comment; checked by the tests). */
        internal val M = Ed25519.decode(hex("5ada7e4bf6ddd9adb6626d32131c6b5c51a1e347a3478f53cfcf441b88eed12e"))
        internal val N = Ed25519.decode(hex("10e3df0ae37d8e7a99b5fe74b44672103dbddcbd06af680d71329a11693bc778"))

        /** adb's names, including the C string's NUL (pairing_auth.cpp passes sizeof). */
        val ADB_CLIENT_NAME = "adb pair client\u0000".toByteArray(Charsets.US_ASCII)
        val ADB_SERVER_NAME = "adb pair server\u0000".toByteArray(Charsets.US_ASCII)

        /** The adb pairing client (Alice) for [password] = pairing code bytes + TLS exported key material. */
        fun adbClient(password: ByteArray, random: SecureRandom = SecureRandom()): Spake2 =
            Spake2(true, ADB_CLIENT_NAME, ADB_SERVER_NAME, password, randomPrivateScalar(random))

        /** The adbd side (Bob); used by the tests to play the phone. */
        internal fun adbServer(password: ByteArray, random: SecureRandom = SecureRandom()): Spake2 =
            Spake2(false, ADB_SERVER_NAME, ADB_CLIENT_NAME, password, randomPrivateScalar(random))

        internal fun randomPrivateScalar(random: SecureRandom): BigInteger {
            val b = ByteArray(64).also { random.nextBytes(it) }
            return privateScalarFrom(b)
        }

        /** x25519_sc_reduce then left_shift_3, as BoringSSL does with its 64 random bytes. */
        internal fun privateScalarFrom(random64: ByteArray): BigInteger =
            Ed25519.fromLittleEndian(random64).mod(Ed25519.L).shiftLeft(3)

        internal fun passwordScalar(hash: ByteArray): BigInteger {
            var w = Ed25519.fromLittleEndian(hash).mod(Ed25519.L)
            var order = Ed25519.L
            for (bit in 0..2) {  // add l, 2l, 4l when that bit is set: the result is a multiple of 8
                if (w.testBit(bit)) w += order
                order = order.shiftLeft(1)
            }
            return w
        }

        internal fun sha512(b: ByteArray): ByteArray = MessageDigest.getInstance("SHA-512").digest(b)

        internal fun hex(s: String): ByteArray = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }
    }
}
